    "record": {
      "citation": "Ika, A.R.; Lin, S.F.; Wang, C.L.; Chang-Chien, G.P.; Huang, B.W. Occurrence, partitioning, and fate of per- and polyfluoroalkyl substances (PFAS) in a full-scale AO-MBR-RO municipal WWTP. J. Water Process Eng. 2025, 80, 109196.",
      "comparability": {
        "evidence_locator_ids": [
          "S11-E02",
          "S11-E03",
          "S11-E06",
          "S11-E08"
        ],
        "reason": "Field observations in a single full-scale AO\u2013MBR\u2013RO WWTP with inherently variable municipal wastewater matrix and no paired clean-water controls; results characterize real-matrix partitioning and redistribution rather than controlled matrix effects and are thus more suitable for qualitative insights than direct quantitative comparison across treatment technologies or matrices.",
        "status": "descriptive_only"
      },
      "doi_or_stable_url": "https://doi.org/10.1016/j.jwpe.2025.109196",
      "endpoints": [
        {
          "endpoint_type": "removal",
          "evidence_locator_ids": [
            "S11-E01",
            "S11-E02",
            "S11-E08"
          ],
          "interpretation": "Stage-wise PFAS reduction was evaluated by comparing concentrations and daily mass loads across AO, MBR, and RO units. The MBR achieved partial \u03a3PFAS reduction (~61%), while RO achieved high PFAS rejection (>94% from feed to permeate) but concentrated PFAS in brine rather than destroying them.",
          "reported_term": "removal efficiency and reduction"
        },
        {
          "endpoint_type": "separation",
          "evidence_locator_ids": [
            "S11-E01",
            "S11-E02",
            "S11-E03",
            "S11-E06",
            "S11-E07",
            "S11-E08"
          ],
          "interpretation": "RO performance was assessed as separation/rejection of PFAS from the aqueous phase into the brine. Compound-specific partitioning between aqueous streams and sludge was quantified, showing preferential accumulation of PFOS and long-chain PFCAs in sludge and continued mobility of short-chain and emerging PFAS in aqueous phases.",
          "reported_term": "rejection and partitioning"
        },
        {
          "endpoint_type": "parent_compound_loss",
          "evidence_locator_ids": [
            "S11-E02",
            "S11-E03",
            "S11-E06",
            "S11-E07",
            "S11-E08"
          ],
          "interpretation": "Concentration changes of individual PFAS across stages (e.g., PFOS, PF4OPeA) were tracked. AO mobilized matrix-bound PFAS and likely transformed precursors, leading to apparent increases in terminal PFAS (e.g., PFOS spikes post-AO, PF4OPeA increases after primary sedimentation) rather than true destruction.",
          "reported_term": "concentration changes and apparent increases"
        },
        {
          "endpoint_type": "transformation",
          "evidence_locator_ids": [
            "S11-E02",
            "S11-E03",
            "S11-E06",
            "S11-E07"
          ],
          "interpretation": "Authors hypothesized in-situ precursor transformation, particularly of sulfonamides and ether-type PFAS, during biological treatment and anaerobic digestion, contributing to increased loads of terminal PFAS such as PFOS and other PFAAs. Transformation was inferred from load increases rather than direct precursor quantification in the provided excerpts.",
          "reported_term": "precursor transformation"
        },
        {
          "endpoint_type": "other",
          "evidence_locator_ids": [
            "S11-E01",
            "S11-E02",
            "S11-E03",
            "S11-E06"
          ],
          "interpretation": "Mass-balance analysis of daily PFAS loads across aqueous and sludge streams showed that the AO\u2013MBR\u2013RO system largely redistributed PFAS between effluent, RO brine, and biosolids rather than eliminating them, with ~89% of influent PFAS mass appearing in final effluent and 159% in sludge, indicating net enrichment via matrix concentration and precursor conversion.",
          "reported_term": "mass balance and fate"
        }
      ],
